	if err != nil {
		notFoundOrServer(w, err)
		return
	}
	defer rows.Close()
	items := []map[string]any{}
	for rows.Next() {
		var id, bid, name, code, bname string
		var order int
		if rows.Scan(&id, &bid, &name, &code, &order, &bname) == nil {
