}

// validateMCPOAuthSettings 는 저장 트랜잭션 안의 값을 통째로 읽어 검증한다.
// 요청이 일부 키만 보내도 나머지와 합친 결과가 말이 되어야 한다.
func (s *Server) validateMCPOAuthSettings(ctx context.Context, tx pgx.Tx) error {
	rows, err := tx.Query(ctx, `SELECT key,value FROM settings WHERE key LIKE $1 OR key='oidc.issuer_url'`, mcpOAuthKeyPrefix+"%")
	if err != nil {
		return err
	}
	defer rows.Close()
	values := map[string]string{}
	for rows.Next() {
		var key, value string
		if err := rows.Scan(&key, &value); err != nil {
			return err
		}
		values[key] = value
	}
	return readMCPOAuthConfig(values).validate()
}

// oauthProviders 는 issuer 별 discovery 결과를 캐시한다. discovery 는 Keycloak
// 으로의 왕복이고 그 뒤의 JWKS 가 모든 토큰을 검증하므로, 요청마다 하면 MCP
// 호출마다 Keycloak 지연이 앞에 붙는다. go-oidc 는 모르는 key id 를 만나면 키
// 집합을 다시 받아오므로 키 회전에 캐시 무효화가 필요 없다.
# syntax=docker/dockerfile:1.7
FROM node:24-alpine AS web
WORKDIR /src/web
COPY web/package.json web/package-lock.json ./
RUN npm ci --ignore-scripts && node node_modules/esbuild/install.js
COPY web/ ./
RUN npm run build

FROM golang:1.24-bookworm AS backend
WORKDIR /src
COPY go.mod go.sum ./
RUN go mod download
COPY cmd/ cmd/
COPY internal/ internal/
RUN rm -rf cmd/seaton/webdist && mkdir -p cmd/seaton/webdist
COPY --from=web /src/web/dist/ cmd/seaton/webdist/
ARG VERSION=dev
ARG COMMIT=unknown
ARG BUILT_AT=unknown
RUN CGO_ENABLED=0 GOOS=linux go build -trimpath \
    -ldflags="-s -w -X main.version=${VERSION} -X main.commit=${COMMIT} -X main.builtAt=${BUILT_AT}" \
    -o /out/seaton ./cmd/seaton

FROM debian:bookworm-slim
LABEL org.opencontainers.image.title="SeatOn" \
      org.opencontainers.image.description="Offline-ready smart office seat management" \
      org.opencontainers.image.source="https://github.com/hkjang/seaton"
RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates tzdata poppler-utils \
    && rm -rf /var/lib/apt/lists/* \
    && groupadd --system --gid 10001 seaton \
    && useradd --system --uid 10001 --gid seaton --home-dir /var/lib/seaton seaton \
    && install -d -o seaton -g seaton -m 0700 /var/lib/seaton
COPY --from=backend --chown=seaton:seaton /out/seaton /usr/local/bin/seaton
USER 10001:10001
EXPOSE 8080
VOLUME ["/var/lib/seaton"]
ENTRYPOINT ["/usr/local/bin/seaton"]
